DECLARE
 ref UUID DEFAULT gen_random_uuid();
BEGIN
 IF account_from = account_to THEN
  RETURN;
 END IF;
 IF (SELECT SUM(amount) FROM account_transactions WHERE account_id = account_from) >= transfer_amount
 THEN
  INSERT INTO account_transactions (account_id, amount, reference)
  VALUES (account_from, -transfer_amount, ref),
         (account_to, transfer_amount, ref);
 END IF;
END

DECLARE
 ref UUID DEFAULT gen_random_uuid();
BEGIN
 INSERT INTO account_transactions (account_id, amount, reference)
 VALUES (deposit_account, deposit_amount, ref);
END

DECLARE
 ref UUID DEFAULT gen_random_uuid();
BEGIN
 IF (SELECT SUM(amount) FROM account_transactions WHERE account_id = withdrawal_account) >= withdrawal_amount
 THEN
  INSERT INTO account_transactions (account_id, amount, reference)
  VALUES (withdrawal_account, -withdrawal_amount, ref);
 END IF;
END
